  `lng` decimal(9,6) NOT NULL,
  `type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `religion` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Hindu',
  `deity` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `built_year` smallint DEFAULT NULL,
  `built_text` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `dynasty` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'unknown',
  `architecture` varchar(400) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `unesco` tinyint(1) NOT NULL DEFAULT '0',
  `short_text` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `story` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `legend` text COLLATE utf8mb4_unicode_ci,
  `facts` json NOT NULL,
