  `quake_2015` varchar(400) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `image_url` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `image_page` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `image_credit` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `tags` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `sources` json DEFAULT NULL,
  `short_np` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `story_np` text COLLATE utf8mb4_unicode_ci,
  `legend_np` text COLLATE utf8mb4_unicode_ci,
  `facts_np` json DEFAULT NULL,
  `quake_np` varchar(900) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `festivals` json DEFAULT NULL,
